import math
from collections import Counter

try:
    LocalRAGIndex
except NameError:
    class LocalRAGIndex:
        def __init__(self, documents):
            self.documents = list(documents)

        @staticmethod
        def _vec(text):
            text = " " + text.lower() + " "
            return Counter(text[i:i + 3] for i in range(len(text) - 2))

        def _dense(self, query, doc):
            a, b = self._vec(query), self._vec(doc)
            dot = sum(a[k] * b[k] for k in a)
            na = math.sqrt(sum(v * v for v in a.values()))
            nb = math.sqrt(sum(v * v for v in b.values()))
            return dot / (na * nb) if na and nb else 0.0

        def _sparse(self, query, doc):
            q = query.lower().split()
            d = set(doc.lower().split())
            return sum(1 for t in q if t in d) / len(q) if q else 0.0

        def search(self, query, top_k=3, dense_weight=0.5, sparse_weight=0.5):
            scored = []
            for doc in self.documents:
                s = (dense_weight * self._dense(query, doc)
                     + sparse_weight * self._sparse(query, doc))
                scored.append({"document": doc, "score": s})
            scored.sort(key=lambda r: -r["score"])
            return scored[:top_k]


class WeightTuner:
    def __init__(self, index, test_cases: list[dict]):
        self.index = index
        self.test_cases = test_cases

    def evaluate(self, dense_weight: float,
                 sparse_weight: float) -> float:
        if not self.test_cases:
            return 0.0
        correct = 0
        for case in self.test_cases:
            results = self.index.search(
                case["query"], top_k=1,
                dense_weight=dense_weight, sparse_weight=sparse_weight,
            )
            if results and results[0]["document"] == case["expected"]:
                correct += 1
        return float(correct / len(self.test_cases))

    def find_best_weights(self) -> dict:
        best = None
        for step in range(10, -1, -1):  # highest dense first so ties prefer it
            dense = round(step / 10, 1)
            sparse = round(1.0 - dense, 1)
            acc = self.evaluate(dense, sparse)
            if best is None or acc > best["accuracy"]:
                best = {"dense_weight": dense, "sparse_weight": sparse,
                        "accuracy": acc}
        return best


index = LocalRAGIndex([
    "python decorators wrap functions",
    "asyncio handles concurrent IO",
    "the GIL prevents multi-threading",
])

tuner = WeightTuner(index, [
    {"query": "decorators", "expected": "python decorators wrap functions"},
    {"query": "concurrent", "expected": "asyncio handles concurrent IO"},
    {"query": "GIL", "expected": "the GIL prevents multi-threading"},
])

acc = tuner.evaluate(0.7, 0.3)
print(acc)

best = tuner.find_best_weights()
print(best["accuracy"])
print(best["dense_weight"] + best["sparse_weight"])
